  Header.flags.<reserved0>               offset=AbsoluteStatic(0x02:5) size=Fixed(3bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  Header.length                          offset=AbsoluteStatic(0x03) size=Fixed(2) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  Header.rec_count                       offset=AbsoluteStatic(0x05) size=Fixed(2) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  Header.seq                             offset=AbsoluteStatic(0x07) size=Fixed(4) align=Aligned(1) repr=ValueConverted atomic=NonAtomic

struct Message size=11 mutate=Shifting address=Unstable repr=ValueConverted atomic=NonAtomic
  Message.hdr                            offset=AbsoluteStatic(0x00) size=Fixed(11) align=Aligned(8) repr=ValueConverted atomic=NonAtomic
  Message.hdr.version                    offset=AbsoluteStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
